import socket
import ssl
from tls_client import wrap_client_socket


def fetch_greeting(host: str, port: int, cafile: str, server_hostname: str = None) -> bytes:
    """Open a TLS connection to host:port, verify server cert and hostname, return greeting bytes.

    The greeting is the bytes sent by the server up to and including the first newline,
    or until the connection closes, at most 4096 bytes.

    Raises ssl.SSLError or ssl.CertificateError on verification failure.
    """
    if server_hostname is None:
        server_hostname = host

    with socket.create_connection((host, port)) as sock:
        with wrap_client_socket(sock, server_hostname, cafile) as tls_sock:
            # Read up to 4096 bytes or until newline
            data = bytearray()
            while len(data) < 4096:
                chunk = tls_sock.recv(4096 - len(data))
                if not chunk:
                    # Connection closed
                    break
                data.extend(chunk)
                if b"\n" in chunk:
                    # Stop after first newline
                    break
            # Return bytes up to and including first newline if present
            newline_index = data.find(b"\n")
            if newline_index != -1:
                return bytes(data[:newline_index + 1])
            else:
                return bytes(data)

import ssl
import socket
from tls_client import wrap_client_socket


def fetch_greeting(host: str, port: int, cafile: str, server_hostname: str = None) -> bytes:
    """Open a TLS connection to host:port, verify the server cert against cafile and hostname,
    and return the server's greeting bytes up to and including the first newline or until
    connection closes (max 4096 bytes)."""
    if server_hostname is None:
        server_hostname = host

    # Create a TCP socket and connect
    sock = socket.create_connection((host, port))
    try:
        # Wrap the socket with TLS and verify certificate and hostname
        tls_sock = wrap_client_socket(sock, server_hostname, cafile)
        try:
            # Read up to 4096 bytes or until first newline
            greeting = bytearray()
            while len(greeting) < 4096:
                chunk = tls_sock.recv(4096 - len(greeting))
                if not chunk:
                    # Connection closed by server
                    break
                greeting.extend(chunk)
                if b'\n' in chunk:
                    # Found newline, stop reading
                    break
            # Return bytes up to and including first newline if present
            newline_index = greeting.find(b'\n')
            if newline_index != -1:
                return bytes(greeting[:newline_index + 1])
            else:
                return bytes(greeting)
        finally:
            tls_sock.close()
    finally:
        sock.close()
